'use strict'

const fs = require('node:fs')
const path = require('node:path')
const YAML = require('yaml')

/**
 * Write a generated local playbook snapshot (gitignored build artifact).
 *
 * @param {object} playbook
 * @param {string} outPath
 */
function writeResolvedPlaybook (playbook, outPath) {
  const dir = path.dirname(outPath)
  fs.mkdirSync(dir, { recursive: true })
  const clone = structuredClone(playbook)
  if (clone.content?.sources) {
    for (const src of clone.content.sources) {
      delete src._local
      delete src._remote
    }
  }
  const header =
    '# Generated by @antora-supplemental/antora-local-content-sources — do not commit.\n' +
    '# Rebuilt on each local Antora run when local source resolution is enabled.\n'
  fs.writeFileSync(outPath, header + YAML.stringify(clone), 'utf8')
}

module.exports = { writeResolvedPlaybook }
